class Solution:
    def maxDistToClosest(self, seats: List[int]) -> int:
        prev, result = -1, 1
        for i in range(len(seats)):
            if seats[i]:
                if prev < 0:
                    result = i
                else:
                    result = max(result, (i-prev)//2)
                prev = i
        return max(result, len(seats)-1-prev)

class SegmentTree:
    def __init__(self, xs):
        #cnts[v] means that the node's interval is active
        self.cnts = defaultdict(int)
        #total[v] length of active intervals that are contained the node's interval
        self.total = defaultdict(int)
        self.xs = xs

    def update(self, v, tl, tr, l, r, h):
        #node interval [tl,tr] does not overlap with query interval [l,r]
        if r < tl or tr < l: return
        #node interval is included in the query interval
        if l <= tl and tr <= r:
            self.cnts[v] += h
        else:
            tm = (tl + tr)//2
            self.update(v*2, tl, tm, l, r, h)
            self.update(v*2+1, tm+1, tr, l, r, h)
        #node interval is included in the active interval
        if self.cnts[v] > 0:
            self.total[v] = self.xs[tr + 1] - self.xs[tl]
        else:
            self.total[v] = self.total[v*2] + self.total[v*2+1]
        return self.total[v]

class Solution:
    def rectangleArea(self, rectangles):
        #index i means the interval from xs[i] to xs[i+1]
        xs = sorted(set([x for x1, y1, x2, y2 in rectangles for x in [x1, x2]]))
        xs_i = {x:i for i, x in enumerate(xs)}
        st = SegmentTree(xs)
        L = []
        for x1, y1, x2, y2 in rectangles:
            L.append([y1, 1, x1, x2])
            L.append([y2, -1, x1, x2])
        L.sort()
        cur_y = cur_x_sum = area = 0
        for y, open_close, x1, x2 in L:
            area += (y - cur_y) * cur_x_sum
            cur_y = y
            #one index corresponds to one interval, that's why we use xs_i[x2]-1 instead of xs_i[x2]
            st.update(1, 0, len(xs) - 1, xs_i[x1], xs_i[x2]-1, open_close)
            cur_x_sum = st.total[1]

        return area % (10 ** 9 + 7)

class SegmentTreeNode:
    def __init__(self, start, end):
        self.start, self.end = start, end
        self.total = self.count = 0
        self._left = self._right = None

    def mid(self):
        return (self.start+self.end) // 2

    def left(self):
        self._left = self._left or SegmentTreeNode(self.start, self.mid())
        return self._left

    def right(self):
        self._right = self._right or SegmentTreeNode(self.mid(), self.end)
        return self._right

    def update(self, X, i, j, val):
        if i >= j:
            return 0
        if self.start == i and self.end == j:
            self.count += val
        else:
            self.left().update(X, i, min(self.mid(), j), val)
            self.right().update(X, max(self.mid(), i), j, val)
        if self.count > 0:
            self.total = X[self.end]-X[self.start]
        else:
            self.total = self.left().total + self.right().total
        return self.total

class Solution:
    def rectangleArea(self, rectangles):
        OPEN, CLOSE = 1, -1
        events = []
        X = set()
        for x1, y1, x2, y2 in rectangles:
            events.append((y1, OPEN, x1, x2))
            events.append((y2, CLOSE, x1, x2))
            X.add(x1)
            X.add(x2)
        events.sort()
        X = sorted(X)
        Xi = {x: i for i, x in enumerate(X)}

        st = SegmentTreeNode(0, len(X)-1)
        result = 0
        cur_x_sum = 0
        cur_y = events[0][0]
        for y, typ, x1, x2 in events:
            result += cur_x_sum * (y-cur_y)
            cur_x_sum = st.update(X, Xi[x1], Xi[x2], typ)
            cur_y = y
        return result % (10**9+7)

