    def kSimilarity(self, s1: str, s2: str) -> int:
        n = len(s1)

        def helper(i, curr, dp):
            if curr == s2:
                return 0

            if curr not in dp[i]:
                if curr[i] == s2[i]:
                    dp[i][curr] = helper(i+1, curr, dp)
                else:
                    temp = sys.maxsize
                    for j in range(i+1, n):
                        if curr[j] == s2[i]:
                            temp = min(temp, 1+helper(i+1, curr[:i]+curr[j]+curr[i+1:j]+curr[i]+curr[j+1:], dp))

                    dp[i][curr] = temp
            return dp[i][curr]

        dp = [{} for _ in range(n)]
        return helper(0, s1, dp)

import collections

class Solution:
    def kSimilarity(self, A, B):
        def neighbors(s, B):
            for i, c in enumerate(s):
                if c != B[i]:
                    break
            t = list(s)
            for j in range(i+1, len(s)):
                if t[j] == B[i]:
                    t[i], t[j] = t[j], t[i]
                    yield "".join(t)
                    t[j], t[i] = t[i], t[j]

        q = collections.deque([A])
        lookup = set()
        result = 0
        while q:
            for _ in range(len(q)):
                s = q.popleft()
                if s == B:
                    return result
                for t in neighbors(s, B):
                    if t not in lookup:
                        lookup.add(t)
                        q.append(t)
            result += 1

class Solution:
    def scoreOfParentheses(self, s: str) -> int:

        level = 0
        result = 0
        prev = ""

        for c in s:           
            if c == "(":
                level += 1
            if c == ")":
                if prev == "(":
                    result += 2 ** (level - 1)
                level -= 1                
            prev = c

        return result

class Solution:
    def scoreOfParentheses(self, S):
        stack = [0]
        for c in S:
            if c == '(':
                stack.append(0)
            else:
                last = stack.pop()
                stack[-1] += max(1, 2*last)
        return stack[0]

class Solution:
    def scoreOfParentheses(self, S):
        result, depth = 0, 0
        for i in range(len(S)):
            if S[i] == '(':
                depth += 1
            else:
                depth -= 1
                if S[i-1] == '(':
                    result += 2**depth
        return result
